def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Top_Three_Identity_Theft_Reports_by_Year.csv"
    raw = pd.read_csv(path, header=None, dtype=str, keep_default_na=False)
    return raw.head(40)

def process(topThreeIdTheft):
    import pandas as pd

    df = topThreeIdTheft.copy()

    base = df[df["year"] == 2020][["theftType", "reports"]].rename(columns={"reports": "reports2020"})
    end = df[df["year"] == 2024][["theftType", "reports"]].rename(columns={"reports": "reports2024"})

    growth = base.merge(end, on="theftType", how="inner")
    growth["relativeGrowth"] = (growth["reports2024"] - growth["reports2020"]) / growth["reports2020"]

    out = growth.sort_values(["relativeGrowth", "theftType"], ascending=[False, True]).head(1)[
        ["theftType", "relativeGrowth", "reports2020", "reports2024"]
    ]
    return out.reset_index(drop=True)
